with w as(select * from public.works where id=any(array[214,330,363]::int[])),e as(select * from public.editions where work_id in(select id from w)or isbn_13=any(array['9789022563915','9789044513202','9789060748107']::text[])) select jsonb_build_object('checked_at',clock_timestamp(),'project','qvplwejffhjvxaypmjut','works',(select coalesce(jsonb_agg(to_jsonb(t)order by id),'[]')from w t),'authors',(select coalesce(jsonb_agg(to_jsonb(t)order by id),'[]')from public.authors t where id in(select author_id from w)),'editions',(select coalesce(jsonb_agg(to_jsonb(t)order by id),'[]')from e t),'metadata',(select coalesce(jsonb_agg(to_jsonb(t)order by edition_id),'[]')from public.catalog_edition_metadata t where work_id in(select id from w)),'descriptions',(select coalesce(jsonb_agg(to_jsonb(t)order by work_id,language),'[]')from public.catalog_work_descriptions t where work_id in(select id from w)and language='nl'))as preflight;
